@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--bg:#090d17;--panel:#101725;--panel2:#121c2c;--line:#202c3f;--muted:#758299;--text:#e9eef7;--mint:#a7f3d0;--cyan:#73d6d1;--gold:#edc77a;--purple:#a993f7;--sans:'DM Sans','Space Grotesk',sans-serif;--mono:'DM Mono',monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 68% 0%,rgba(36,64,96,.18),transparent 44%)}button{font:inherit;color:inherit}.app-shell{max-width:1600px;margin:auto}.topbar{height:76px;border-bottom:1px solid #1c2637;display:flex;align-items:center;padding:0 40px;gap:26px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#f4f6fb;font-size:15px;letter-spacing:2px;font-weight:800;line-height:1}.brand-light{font-weight:500;color:#9caabe}.brand small{display:block;color:#69758a;font:9px var(--mono);letter-spacing:1.55px;margin-top:6px}.brand-mark{width:35px;height:35px;border:1px solid #5fe0c0;border-radius:11px;color:#83ebc7;display:grid;place-items:center;position:relative;font-size:19px;box-shadow:0 0 17px #42cfa122}.brand-mark span{position:absolute;width:5px;height:5px;border-radius:50%;background:#dfc77b;right:4px;top:4px}.season{margin:auto;color:#8591a5;font:10px var(--mono);letter-spacing:1.3px}.season i,.live-pulse,.signal-dot,.tiny-live,.site-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#78e3b0;box-shadow:0 0 9px #78e3b0;margin-right:8px}.season span{color:#39465b;margin:0 8px}.top-level{display:flex;align-items:center;gap:12px;color:#77849b;font:9px var(--mono);letter-spacing:1px}.top-level b{background:#172438;border:1px solid #283955;padding:8px 10px;color:#afbdd2;font-size:10px;font-weight:500;letter-spacing:.5px}.sound-button{background:none;border:1px solid var(--line);border-radius:8px;color:#91a4ba;height:34px;width:38px;cursor:pointer}.sound-button:hover{border-color:var(--cyan);color:var(--cyan)}
.resource-bar{min-height:78px;border-bottom:1px solid #1c2637;display:flex;align-items:center;padding:0 40px;gap:0;overflow-x:auto;scrollbar-width:none}.resource-bar::-webkit-scrollbar{display:none}.resource-card{display:flex;align-items:center;gap:12px;padding:0 25px;border-right:1px solid #202b3c;min-width:154px;height:38px}.resource-card:first-child{padding-left:0}.resource-card:last-child{border:0}.resource-icon{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;font-size:15px}.resource-card.rock .resource-icon{background:#52607122;color:#9aa8bb}.resource-card.iron .resource-icon{background:#a6bac622;color:#c1d0dd}.resource-card.gold .resource-icon{background:#d6ad4d22;color:#edc77a}.resource-card.platinum .resource-icon{background:#95a9d322;color:#c4d2ec}.resource-card.iridium .resource-icon{background:#bd84d322;color:#d4a0f1}.resource-label{font:9px var(--mono);letter-spacing:1px;color:#7f8ca0}.resource-value{font-size:15px;font-weight:700;margin-top:3px;letter-spacing:.2px}.resource-value small{font-size:10px;font-weight:500;color:#8290a4;margin-left:4px}.resource-card.locked{opacity:.42}.resource-card .income{font:9px var(--mono);color:#64cfa7;margin-left:3px}
.workspace{display:grid;grid-template-columns:220px minmax(0,1fr);min-height:calc(100vh - 154px)}.sidebar{border-right:1px solid #1c2637;padding:34px 16px 22px 24px;display:flex;flex-direction:column}.nav-label{font:9px var(--mono);letter-spacing:1.8px;color:#526078;padding:0 12px 15px}.main-nav{display:grid;gap:6px}.nav-item{width:100%;display:flex;align-items:center;gap:12px;text-align:left;background:transparent;border:1px solid transparent;border-radius:8px;color:#8996aa;padding:11px 12px;cursor:pointer;font-size:12px;transition:.18s}.nav-item:hover{background:#121c2a;color:#d8e2ee}.nav-item.active{color:#c3ffe7;background:linear-gradient(90deg,#17392f77,#142c2b33);border-color:#255747}.nav-icon{font-size:17px;width:19px;text-align:center;color:#70819a}.nav-item.active .nav-icon{color:#8ce8bf}.nav-chevron{margin-left:auto;font-size:18px;color:#80deae}.nav-badge{margin-left:auto;color:#a6f3d0;background:#204337;border-radius:20px;padding:3px 7px;font:9px var(--mono)}.nav-badge.amber{color:#f4d184;background:#493a22}.sidebar-bottom{margin-top:auto}.signal-card{display:flex;align-items:flex-start;background:#111b29;border:1px solid #202e40;border-radius:9px;padding:12px 10px}.signal-dot{flex:none;margin-top:4px;width:5px;height:5px}.signal-card b{display:block;font:8px var(--mono);letter-spacing:.7px;color:#acc0d2}.signal-card small{display:block;color:#637189;font:9px var(--mono);margin-top:7px}.version{font:8px var(--mono);letter-spacing:.7px;color:#515e72;margin:17px 4px 0}.version span{float:right}
.main-content{max-width:1400px;width:100%;padding:28px 40px 30px;margin:0 auto}.planet-card{height:270px;border:1px solid #253247;border-radius:12px;position:relative;overflow:hidden;background:linear-gradient(105deg,#131e2d 0%,#111b29 42%,#0d1624 100%);display:flex;box-shadow:0 16px 50px #0002}.planet-copy{width:47%;z-index:2;padding:27px 0 16px 28px}.eyebrow{font:9px var(--mono);letter-spacing:1.4px;color:#8190a4}.planet-copy .eyebrow{color:#9eafbf}.planet-copy .live-pulse{width:6px;height:6px}.eyebrow-divider{color:#465368;margin:0 8px}h1{font-size:36px;letter-spacing:-1.3px;margin:15px 0 5px;line-height:1;font-weight:600}h1 span{font:14px var(--mono);color:#b4a1f2;vertical-align:middle;letter-spacing:1px;margin-left:4px}.planet-description{color:#95a2b5;font-size:12px;margin:10px 0 16px}.planet-tags{display:flex;gap:8px}.planet-tags span{font:8px var(--mono);letter-spacing:.5px;color:#92a4b9;border:1px solid #2a394d;border-radius:4px;padding:6px 8px}.site-readout{position:absolute;bottom:40px;color:#c7d2df;font:9px var(--mono);letter-spacing:.9px}.site-dot{width:5px;height:5px;background:#d7b86f;box-shadow:0 0 7px #d7b86f}.planet-art{position:absolute;right:0;top:0;width:61%;height:100%;overflow:hidden;background:radial-gradient(ellipse at 65% 48%,#172944 0%,#111b2b 40%,transparent 72%)}#space-canvas{width:100%;height:100%;display:block}.canvas-label{position:absolute;right:18px;top:18px;text-align:right;font:9px var(--mono);letter-spacing:1.1px;color:#8295af}.canvas-label small{display:block;color:#50627b;font-size:8px;margin-top:5px}.scanline{position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,#c3e3ff04 4px)}.planet-footer{position:absolute;bottom:0;left:0;right:0;height:30px;background:#0a111d96;border-top:1px solid #ffffff0c;display:flex;align-items:center;gap:20px;padding:0 15px;color:#687b93;font:8px var(--mono);letter-spacing:1px}.planet-footer span:last-child{margin-left:auto}.planet-footer b{color:#a6bad2;font-weight:400}.tiny-live{width:5px;height:5px;margin-right:4px}.mobile-heading{display:none}
.section-heading{display:flex;align-items:end;justify-content:space-between;margin:27px 0 15px}.section-heading h2{margin:6px 0 0;font-size:20px;letter-spacing:-.4px;font-weight:600}.rate-pill{display:flex;gap:9px;align-items:center;border:1px solid #233448;border-radius:8px;background:#101b29;padding:7px 11px}.rate-icon{color:#77dfb0;font-size:17px}.rate-pill b{display:block;font:12px var(--mono);color:#bcf5dc}.rate-pill small{display:block;font:8px var(--mono);color:#65758a;letter-spacing:.9px;margin-top:3px}.view-content{min-height:190px}.overview-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(270px,.9fr);gap:14px}.panel{background:var(--panel);border:1px solid #222f42;border-radius:10px;overflow:hidden}.panel-heading{height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;border-bottom:1px solid #202c3e}.panel-heading h3{margin:0;font-size:12px;font-weight:600;letter-spacing:.2px}.panel-heading small{font:8px var(--mono);color:#697a91;letter-spacing:1px}.ship-row{display:flex;align-items:center;padding:14px 16px 6px;gap:12px}.ship-portrait{height:38px;width:42px;border-radius:8px;background:#1a293a;color:#87dfc2;display:grid;place-items:center;font-size:19px;border:1px solid #2a3a4d}.ship-name{font-size:11px;font-weight:600}.ship-sub{font:8px var(--mono);color:#708098;margin-top:4px}.ship-status{margin-left:auto;font:8px var(--mono);letter-spacing:.7px;color:#87dcb5}.ship-status:before{content:'';display:inline-block;width:5px;height:5px;border-radius:50%;background:#78e3b0;margin-right:5px}.mission-progress{padding:9px 16px 14px}.progress-meta{display:flex;justify-content:space-between;font:9px var(--mono);color:#8e9bb0;margin-bottom:8px}.progress-meta b{font-weight:400;color:#d2dfec}.progress-track{height:5px;background:#202d40;border-radius:5px;overflow:hidden}.progress-fill{height:100%;background:linear-gradient(90deg,#54bca9,#9af0c6);border-radius:5px;box-shadow:0 0 10px #6ae1b377;transition:width .5s linear}.mission-bottom{display:flex;justify-content:space-between;color:#697a90;font:8px var(--mono);padding-top:8px}.mission-bottom b{color:#c0ccda;font-weight:400}.panel-action{border-top:1px solid #202c3e;display:flex;align-items:center;justify-content:space-between;padding:9px 16px;background:#111a27}.panel-action span{font:8px var(--mono);color:#73849b}.panel-action button,.primary-button{background:#b4f1d0;color:#12271f;border:0;border-radius:6px;padding:8px 12px;font-weight:700;font-size:9px;letter-spacing:.3px;cursor:pointer;transition:.16s}.panel-action button:hover,.primary-button:hover{background:#d5ffe8;transform:translateY(-1px)}.panel-action button:disabled,.primary-button:disabled{opacity:.38;cursor:not-allowed;transform:none}.upgrade-list{padding:0 14px}.upgrade-row{display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid #1e2939}.upgrade-row:last-child{border-bottom:0}.upgrade-icon{width:31px;height:31px;border-radius:7px;background:#20253a;display:grid;place-items:center;color:#b49eff;font-size:15px}.upgrade-info{min-width:0;flex:1}.upgrade-name{font-size:10px;font-weight:600}.upgrade-description{font-size:8px;color:#74839a;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.upgrade-cost{text-align:right;font:8px var(--mono);color:#aab8ca;white-space:nowrap}.upgrade-cost button{display:block;margin:5px 0 0 auto;background:#1d302d;color:#a4efd0;border:1px solid #325447;padding:4px 7px;border-radius:4px;font:8px var(--mono);cursor:pointer}.upgrade-cost button:hover{background:#28473c}.upgrade-cost button:disabled{opacity:.35;cursor:not-allowed}.unlock-row{background:#111b28;border:1px dashed #35465b;border-radius:7px;padding:10px 11px;margin:6px 0 11px;color:#8f9db0;font:9px var(--mono);display:flex;align-items:center;justify-content:space-between}.unlock-row b{color:#e5cc8d;font-weight:500}.resource-mini{font:8px var(--mono);color:#8b9bb1}.multi-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.detail-card{background:var(--panel);border:1px solid #222f42;border-radius:10px;padding:16px}.detail-card h3{font-size:12px;margin:0 0 6px}.detail-card p{color:#8795a9;font-size:10px;line-height:1.55;margin:5px 0 12px}.metric-line{display:flex;justify-content:space-between;font:9px var(--mono);color:#8190a6;padding:8px 0;border-bottom:1px solid #1e2939}.metric-line b{color:#cad6e4;font-weight:400}.upgrade-buy{display:flex;align-items:center;gap:8px}.upgrade-buy button,.secondary-button{background:#182438;color:#bcd3e2;border:1px solid #33465e;border-radius:5px;padding:7px 9px;font:9px var(--mono);cursor:pointer}.upgrade-buy button:hover,.secondary-button:hover{border-color:#73d6d1;color:#c4fff2}.upgrade-buy button:disabled{opacity:.35;cursor:not-allowed}.upgrade-buy span{font:8px var(--mono);color:#8695a8}.tech-card{min-height:160px;position:relative}.tech-icon{color:#b9a2ff;font-size:24px;margin-bottom:12px}.tech-state{font:8px var(--mono);letter-spacing:1px;color:#8ce1b9}.tech-card.locked{opacity:.54}.ascension-card{background:linear-gradient(120deg,#1d1b32,#151a29 65%,#211d31);border-color:#423958;padding:20px}.ascension-mark{font-size:25px;color:#d2b578;float:right}.ascension-card h3{font-size:16px;margin:0 0 7px}.ascension-card p{font-size:10px;color:#9c9bb2;max-width:590px;line-height:1.6}.ascension-stat{display:flex;gap:10px;align-items:center;padding:10px 0 15px;font:9px var(--mono);color:#a09eb6}.ascension-stat b{color:#efd48c;font-size:14px}.ascension-card .primary-button{background:#d9bd7a;color:#2b2414;padding:9px 14px}.ascension-card .primary-button:disabled{background:#756a50;color:#d3c7a8}.warning-note{font:8px var(--mono);color:#77758d;margin-left:11px}.footer-note{text-align:center;color:#57677e;font:8px var(--mono);letter-spacing:.4px;margin-top:21px}.footer-note>span:first-child{color:#71889b;margin-right:5px}.footer-sep{margin:0 8px;color:#354357}.toast{position:fixed;left:50%;bottom:25px;z-index:20;transform:translate(-50%,20px);background:#d7fbe8;color:#14251e;padding:10px 15px;border-radius:7px;font-size:11px;font-weight:700;box-shadow:0 8px 25px #0008;opacity:0;pointer-events:none;transition:.22s}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:1000px){.topbar{padding:0 25px}.resource-bar{padding:0 25px}.workspace{grid-template-columns:180px minmax(0,1fr)}.sidebar{padding-left:15px}.main-content{padding:24px}.planet-copy{width:51%}.planet-art{width:60%}.overview-grid{grid-template-columns:minmax(0,1.2fr) minmax(250px,.8fr)}}
@media(max-width:720px){.topbar{height:59px;padding:0 15px;gap:13px}.brand{font-size:13px}.brand-mark{width:31px;height:31px}.brand small{font-size:7px}.season,.top-level{display:none}.sound-button{margin-left:auto}.resource-bar{min-height:65px;padding:0 14px}.resource-card{min-width:125px;padding:0 13px;gap:8px}.resource-card:first-child{padding-left:0}.resource-icon{width:27px;height:27px}.resource-value{font-size:13px}.workspace{display:block;min-height:calc(100vh - 124px)}.sidebar{position:fixed;z-index:10;bottom:0;left:0;right:0;height:61px;padding:4px 8px max(5px,env(safe-area-inset-bottom));background:#0b111c;border-top:1px solid #273447;border-right:0;display:block}.nav-label,.sidebar-bottom{display:none}.main-nav{display:grid;grid-template-columns:repeat(4,1fr);gap:3px}.nav-item{border-radius:7px;padding:5px 2px;display:flex;flex-direction:column;justify-content:center;gap:2px;font-size:8px;height:49px}.nav-icon{font-size:16px}.nav-chevron,.nav-badge{display:none}.nav-item.active{border-color:transparent;background:#1b332f}.main-content{padding:13px 13px 84px}.mobile-heading{display:flex;justify-content:space-between;align-items:center;margin:0 2px 10px;color:#7789a0;font:8px var(--mono);letter-spacing:.7px}.mobile-heading b{font-weight:400;color:#a0aec0}.planet-card{height:232px}.planet-copy{width:65%;padding:20px 0 10px 17px}.planet-copy .eyebrow{font-size:7px;letter-spacing:.8px}.planet-copy .live-pulse{margin-right:4px}.eyebrow-divider{margin:0 4px}h1{font-size:30px;margin-top:14px}.planet-description{font-size:10px;max-width:200px;line-height:1.5}.planet-tags{gap:4px}.planet-tags span{font-size:7px;padding:5px 6px}.site-readout{bottom:42px;font-size:7px}.planet-art{width:67%;opacity:.84;background:radial-gradient(ellipse at 75% 48%,#172944 0%,#111b2b 40%,transparent 73%)}.canvas-label{right:11px;top:11px;font-size:7px}.canvas-label small{font-size:6px}.planet-footer{height:29px;padding:0 9px;gap:10px;font-size:7px}.section-heading{margin:21px 0 12px}.section-heading h2{font-size:18px}.rate-pill{padding:6px 8px}.overview-grid{grid-template-columns:1fr;gap:11px}.panel-heading{height:43px}.upgrade-row{padding:11px 0}.multi-grid{grid-template-columns:1fr}.detail-card{padding:14px}.footer-note{line-height:1.6;margin:14px 0 0}.footer-sep{margin:0 4px}}
@media(max-width:380px){.resource-card{min-width:112px;padding:0 9px}.resource-label{font-size:8px}.planet-card{height:217px}.planet-copy{width:72%}.planet-art{width:71%}.planet-footer{gap:6px;font-size:6px}.planet-footer span:nth-child(2){display:none}.planet-footer span:last-child{font-size:6px}}

(() => {
  'use strict';
  const RESOURCES = [
    {id:'rock',name:'Rock',symbol:'◈',color:'rock',value:1,unlock:0},
    {id:'iron',name:'Iron',symbol:'⬡',color:'iron',value:4,unlock:600},
    {id:'gold',name:'Gold',symbol:'✧',color:'gold',value:12,unlock:4200},
    {id:'platinum',name:'Platinum',symbol:'⬢',color:'platinum',value:40,unlock:22000},
    {id:'iridium',name:'Iridium',symbol:'✦',color:'iridium',value:130,unlock:100000}
  ];
  const UPGRADES = [
    {id:'drill',name:'Laser drill array',icon:'⌁',desc:'More ore hauled on every expedition.',base:45,scale:1.55,effect:s=>`+${Math.round((1+s.upgrades.drill)*55)}% cargo capacity`},
    {id:'engine',name:'Ion drive tuning',icon:'➤',desc:'Shorter routes mean faster returns.',base:70,scale:1.7,effect:s=>`−${Math.min(70,s.upgrades.engine*8)}% trip time`},
    {id:'bay',name:'Hangar expansion',icon:'⌗',desc:'Build another autonomous mining ship.',base:240,scale:2.1,effect:s=>`${s.ships.length} ship${s.ships.length===1?'':'s'} in your fleet`}
  ];
  const TECHS = [
    {id:'scanner',name:'Deep-field scanners',icon:'⌖',desc:'Locate richer deposits across the belt.',cost:{iron:18},effect:'+25% mining yield',req:1},
    {id:'automation',name:'Autonomous routing',icon:'⟳',desc:'AI plots the most profitable extraction route.',cost:{iron:55,gold:5},effect:'All ships mine 35% faster',req:2},
    {id:'refinery',name:'Zero-loss refinery',icon:'◇',desc:'Recover valuable ore from every fragment.',cost:{gold:40,platinum:3},effect:'+50% mining yield',req:3},
    {id:'quantum',name:'Quantum prospecting',icon:'✧',desc:'Map mineral seams in adjacent sectors.',cost:{platinum:18},effect:'All mining yield doubled',req:4}
  ];
  const META = [
    {id:'legacy',name:'Inherited blueprints',desc:'Start each new run with more cargo capacity.',icon:'⌁',cost:1,effect:s=>`+${s.meta.legacy*20}% base cargo`,max:10},
    {id:'relays',name:'Stellar relay network',desc:'Keep your fleet moving between runs.',icon:'⌘',cost:2,effect:s=>`+${s.meta.relays*8}% base speed`,max:10},
    {id:'survey',name:'Universal survey license',desc:'Begin every run with Iron deposits mapped.',icon:'⌖',cost:4,effect:s=>s.meta.survey?'Iron unlocked from the start':'Unlock Iron at start',max:1}
  ];
  const fresh = () => ({version:1,resources:{rock:120,iron:0,gold:0,platinum:0,iridium:0},unlocked:['rock'],ships:[{progress:0,trips:0}],upgrades:{drill:0,engine:0,bay:0},tech:[],meta:{legacy:0,relays:0,survey:0},metaPoints:0,lifetimeValue:0,totalMined:0,level:1,run:1,last:Date.now(),totalResets:0});
  let state;
  try { state=JSON.parse(localStorage.getItem('orebit-save'))||fresh(); } catch { state=fresh(); }
  state={...fresh(),...state,resources:{...fresh().resources,...state.resources},upgrades:{...fresh().upgrades,...state.upgrades},meta:{...fresh().meta,...state.meta}};
  const fmt=n=>{if(n>=1e9)return (n/1e9).toFixed(2)+'B';if(n>=1e6)return (n/1e6).toFixed(2)+'M';if(n>=1e4)return (n/1e3).toFixed(1)+'K';if(n>=1000)return (n/1e3).toFixed(2)+'K';return Math.floor(n).toLocaleString();};
  const fmtTime=s=>{s=Math.max(0,Math.ceil(s));return s>=60?`${Math.floor(s/60)}m ${String(s%60).padStart(2,'0')}s`:`${s}s`;};
  const costFor=(u)=>Math.ceil(u.base*Math.pow(u.scale,state.upgrades[u.id]));
  const elapsedFor=()=>Math.max(8,24-state.upgrades.engine*1.65)*(1-state.meta.relays*.045)*(state.tech.includes('automation')?.65:1);
  const cargoFor=()=>Math.floor((16+state.upgrades.drill*10)*(1+state.meta.legacy*.2)*(state.tech.includes('scanner')?1.25:1)*(state.tech.includes('refinery')?1.5:1)*(state.tech.includes('quantum')?2:1));
  const mineral= id=>RESOURCES.find(r=>r.id===id);
  const upgradeUnlocks=()=>{
    const unlocked=RESOURCES.filter(r=>state.lifetimeValue>=r.unlock).map(r=>r.id);
    if(state.meta.survey && !unlocked.includes('iron')) unlocked.push('iron');
    RESOURCES.forEach(r=>{if(unlocked.includes(r.id)&&!state.unlocked.includes(r.id)){state.unlocked.push(r.id);notify(`${r.name} deposit discovered — fleet rerouted.`);}});
  };
  const countValue=()=>state.lifetimeValue;
  function chooseResource(ship){const list=RESOURCES.filter(r=>state.unlocked.includes(r.id));return list[Math.floor(ship.trips/list.length)%list.length];}
  function completeTrip(ship){const r=chooseResource(ship);let amount=cargoFor();if(state.upgrades.drill>0)amount+=state.upgrades.drill*3;state.resources[r.id]+=amount;state.totalMined+=amount;state.lifetimeValue+=amount*r.value;ship.trips++;upgradeUnlocks();}
  function advance(seconds){let remain=seconds;for(let s of state.ships){s.progress=(s.progress||0);let period=elapsedFor();s.progress+=remain/period;let loops=0;while(s.progress>=1&&loops++<10000){s.progress--;completeTrip(s);period=elapsedFor();}}
    state.level=1+Math.floor(Math.log10(1+state.lifetimeValue/80));state.last=Date.now();}
  if(state.last){const away=Math.min(28800,Math.max(0,(Date.now()-state.last)/1000));if(away>2)advance(away);}
  let activeView='overview', toastTimer;
  const resourceBar=document.getElementById('resource-bar'), view=document.getElementById('view-content'), toast=document.getElementById('toast');
  function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2600);}
  function save(){state.last=Date.now();try{localStorage.setItem('orebit-save',JSON.stringify(state));}catch{}}
