  function fleetView(){return `<div class="multi-grid"><section class="panel"><div class="panel-heading"><h3>Active fleet</h3><small>${state.ships.length} / ${Math.min(6,1+state.upgrades.bay)} CRAFT</small></div>${state.ships.map(shipMarkup).join('')}<div class="panel-action"><span>Ships mine and return automatically.</span><span style="color:#80dfb4">● ONLINE</span></div></section><section class="detail-card"><div class="eyebrow">FLEET CAPABILITIES</div><h3 style="margin-top:10px">Built for the long haul.</h3><p>Every ship is an independent miner. Expand your hangar to multiply your income, or tune your engines to shorten every expedition.</p><div class="metric-line"><span>Trip duration</span><b>${fmtTime(elapsedFor())}</b></div><div class="metric-line"><span>Ore per trip</span><b>${cargoFor()} units</b></div><div class="metric-line"><span>Fleet size</span><b>${state.ships.length} ship${state.ships.length===1?'':'s'}</b></div></section>${UPGRADES.map(u=>`<section class="detail-card"><div class="eyebrow">FLEET UPGRADE · LV ${state.upgrades[u.id]}</div><h3 style="margin-top:9px">${u.name}</h3><p>${u.desc}</p><div class="metric-line"><span>Current effect</span><b>${u.effect(state)}</b></div><div class="upgrade-buy"><button data-buy-upgrade="${u.id}" ${state.resources.rock<costFor(u)?'disabled':''}>UPGRADE · ${fmt(costFor(u))} ROCK</button><span>LEVEL ${state.upgrades[u.id]}</span></div></section>`).join('')}</div>`;}
  function research(){return `<div class="multi-grid">${TECHS.map((t,i)=>{const done=state.tech.includes(t.id),locked=state.unlocked.length<t.req||(!done&&i>0&&!state.tech.includes(TECHS[i-1].id));return `<section class="detail-card tech-card ${locked?'locked':''}"><div class="tech-icon">${t.icon}</div><div class="tech-state">${done?'✓ RESEARCH COMPLETE':locked?'◌ RESEARCH LOCKED':'AVAILABLE FOR RESEARCH'}</div><h3 style="margin-top:9px">${t.name}</h3><p>${t.desc}</p><div class="metric-line"><span>Effect</span><b>${t.effect}</b></div><div class="upgrade-buy"><button data-tech="${t.id}" ${done||locked||!hasCost(t.cost)?'disabled':''}>${done?'COMPLETED':`RESEARCH · ${costText(t.cost)}`}</button>${locked?`<span>MAP ${t.req} DEPOSITS</span>`:''}</div></section>`;}).join('')}</div>`;}
