}</h3><p>${m.desc}</p><div class="metric-line"><span>Current bonus</span><b>${m.effect(state)}</b></div><div class="upgrade-buy"><button data-meta="${m.id}" ${maxed||state.metaPoints<m.cost?'disabled':''}>${maxed?'MAXED':`UNLOCK · ${m.cost} ✳`}</button></div></section>`;}).join('')}</div>`;}
  function render(){renderResources();document.getElementById('level-top').textContent=`LVL ${String(state.level).padStart(2,'0')}`;document.getElementById('mobile-level').textContent=`COMMANDER · LVL ${String(state.level).padStart(2,'0')}`;document.getElementById('fleet-count').textContent=state.ships.length;document.getElementById('ship-count-label').textContent=`${state.ships.length} SHIP${state.ships.length===1?'':'S'} DEPLOYED`;document.getElementById('ascension-dot').hidden=state.lifetimeValue<250000;let totalRate=state.ships.length*cargoFor()*60/elapsedFor();document.getElementById('income-rate').textContent=fmt(totalRate);document.getElementById('view-title').textContent=({overview:'Your operation',fleet:'Fleet command',research:'Research lab',prestige:'Ascension'})[activeView];view.innerHTML=({overview,fleet:fleetView,research,prestige})[activeView]();}
